window.CubeApiDocs.define("api-Data_Management-新增提示词",{"id":"api-Data_Management-新增提示词","versions":[{"version":"1.0.0","toc":[{"id":"overview","title":"用途与调用说明"},{"id":"request-example","title":"请求示例"},{"id":"parameters","title":"路径与通用参数"},{"id":"body","title":"请求体参数"},{"id":"success","title":"成功响应"},{"id":"errors","title":"错误与处理"}],"html":"\u003carticle data-api-id=\"api-Data_Management-新增提示词\">\u003cheader class=\"article-header\">\u003cp class=\"eyebrow\">数据管理 · v1.0.0\u003c/p>\u003ch1 tabindex=\"-1\">Prompt - 新增提示词\u003c/h1>\u003cdiv class=\"endpoint\">\u003cspan class=\"method post\">POST\u003c/span>\u003ccode>/aigc/prompt/add/:token\u003c/code>\u003cbutton type=\"button\" data-copy=\"path\" aria-label=\"复制接口路径\">复制路径\u003c/button>\u003c/div>\u003c/header>\u003csection class=\"doc-section\" id=\"overview\">\u003ch2>用途与调用说明\u003c/h2>\u003cp>给指定触点新增提示词。该接口不设置触点参数则新增提示词对所有触点有效。\u003c/p>\u003c/section>\u003csection class=\"doc-section\" id=\"request-example\">\u003ch2>请求示例\u003c/h2>\u003cdiv class=\"example\">\u003ch3>新增提示词\u003c/h3>\u003cdiv class=\"code-block\">\u003cdiv class=\"code-toolbar\">\u003cspan>json\u003c/span>\u003cbutton type=\"button\" data-copy=\"code\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\"0\">\u003ccode>\u003cspan class=\"token punctuation\">{\u003c/span>\n    \u003cspan class=\"token property\">\"prompts\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token punctuation\">[\u003c/span>\u003cspan class=\"token punctuation\">{\u003c/span>\n        \u003cspan class=\"token property\">\"act\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"充当舆情数据分析师\"\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n        \u003cspan class=\"token property\">\"prompt\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"你是舆情分析师，帮我查阅一下最近半年一汽大众在全网的舆情趋势。\"\u003c/span>\n    \u003cspan class=\"token punctuation\">}\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span> ... \u003cspan class=\"token punctuation\">]\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"contactIds\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token punctuation\">[\u003c/span> \u003cspan class=\"token number\">71816522\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span> \u003cspan class=\"token number\">71816523\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span> \u003cspan class=\"token number\">71816524\u003c/span> \u003cspan class=\"token punctuation\">]\u003c/span>\n\u003cspan class=\"token punctuation\">}\u003c/span>\u003c/code>\u003c/pre>\u003c/div>\u003c/div>\u003cdetails class=\"example lazy-example\">\u003csummary>新增公共提示词\u003c/summary>\u003ctemplate>\u003cdiv class=\"code-block\">\u003cdiv class=\"code-toolbar\">\u003cspan>json\u003c/span>\u003cbutton type=\"button\" data-copy=\"code\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\"0\">\u003ccode>\u003cspan class=\"token punctuation\">{\u003c/span>\n    \u003cspan class=\"token property\">\"prompts\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token punctuation\">[\u003c/span>\u003cspan class=\"token punctuation\">{\u003c/span>\n        \u003cspan class=\"token property\">\"act\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"充当舆情数据分析师\"\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n        \u003cspan class=\"token property\">\"prompt\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"你是舆情分析师，帮我查阅一下最近半年一汽大众在全网的舆情趋势。\"\u003c/span>\n    \u003cspan class=\"token punctuation\">}\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span> ... \u003cspan class=\"token punctuation\">]\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"contactIds\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token punctuation\">[\u003c/span> \u003cspan class=\"token number\">0\u003c/span> \u003cspan class=\"token punctuation\">]\u003c/span>\n\u003cspan class=\"token punctuation\">}\u003c/span>\u003c/code>\u003c/pre>\u003c/div>\u003c/template>\u003c/details>\u003c/section>\u003csection class=\"doc-section\" id=\"parameters\">\u003ch2>路径与通用参数\u003c/h2>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"Parameter\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型 / 要求\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>token\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003cspan class=\"requirement \">必填\u003c/span>\u003c/td>\u003ctd>\u003cp>授权令牌。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"body\">\u003ch2>请求体参数\u003c/h2>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"字段说明\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型 / 要求\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>prompts\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Array\u003c/code>\u003cspan class=\"requirement optional\">可选\u003c/span>\u003c/td>\u003ctd>\u003cp>新增的提示词数组。与 \u003ccode>prompt\u003c/code> 二选一。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>prompt\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Object\u003c/code>\u003cspan class=\"requirement optional\">可选\u003c/span>\u003c/td>\u003ctd>\u003cp>单条提示词对象。与 \u003ccode>prompts\u003c/code> 二选一。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>contactIds\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Array\u003c/code>\u003cspan class=\"requirement optional\">可选\u003c/span>\u003c/td>\u003ctd>\u003cp>需要增加提示词的触点ID数组。与 \u003ccode>contactId\u003c/code> 二选一。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>contactId\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Number\u003c/code>\u003cspan class=\"requirement optional\">可选\u003c/span>\u003c/td>\u003ctd>\u003cp>需要增加提示词的触点ID 。与 \u003ccode>contactIds\u003c/code> 二选一。设置为 \u003ccode>0\u003c/code> 表示提示词为公共提示词。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"success\">\u003ch2>成功响应\u003c/h2>\u003cdiv class=\"example\">\u003ch3>应答示例\u003c/h3>\u003cdiv class=\"code-block\">\u003cdiv class=\"code-toolbar\">\u003cspan>json\u003c/span>\u003cbutton type=\"button\" data-copy=\"code\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\"0\">\u003ccode>HTTP/\u003cspan class=\"token number\">1.1\u003c/span> \u003cspan class=\"token number\">200\u003c/span> OK\n\u003cspan class=\"token punctuation\">{\u003c/span>\n    \u003cspan class=\"token property\">\"total\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token number\">12\u003c/span>\n\u003cspan class=\"token punctuation\">}\u003c/span>\u003c/code>\u003c/pre>\u003c/div>\u003c/div>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"Success 200\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>total\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Number\u003c/code>\u003c/td>\u003ctd>\u003cp>已新增数据条目数。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"errors\">\u003ch2>错误与处理\u003c/h2>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"Error 4xx\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>400\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">—\u003c/code>\u003c/td>\u003ctd>\u003cp>数据出错。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>401\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">—\u003c/code>\u003c/td>\u003ctd>\u003cp>Token 无效。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>403\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">—\u003c/code>\u003c/td>\u003ctd>\u003cp>参数错误。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003c/article>"}]});
